#include<bits/stdc++.h>
using namespace std;
using ll=long long;

int main()
{
    int t;cin>>t;
    for(int i=0;i<t;i++)
    {
        int n,m;cin>>n>>m;
        map<ll,ll>cnt;
        auto isqrt=[&](ll x)
        {
            ll val=sqrtl(x)+5;
            while(val*val>x)val--;
            return val;
        };
        vector<ll>a(n),r(n);
        for(ll&i:a)cin>>i;
        for(ll&i:r)cin>>i;
        for(int i=0;i<n;i++)
        {
            ll aa=a[i],rr=r[i];
            for(ll x=aa-rr;x<=aa+rr;x++)
            {
                cnt[x]=max(cnt[x],2*isqrt(rr*rr-(x-aa)*(x-aa))+1);
            }
        }
        ll ans=0;
        for(auto[x,c]:cnt)ans+=c;
        cout<<ans<<"\n";
    }
}

#include<bits/stdc++.h>
using namespace std;

int main()
{
    mt19937 mt(727);
    uniform_int_distribution uni(1,3);
    int tc;cin>>tc;
    while(tc--)
    {
        int n;cin>>n;
        if(n<0)return 0;
        vector<int>vec(n);
        for(int i=0;i<n;i++)vec[i]=i+1;
        shuffle(begin(vec),end(vec),mt);
        int ii=vec[0],jj=vec[1],kk=vec[2];
        cerr<<n<<endl;
        while(1)
        {
            cout<<"? "<<ii<<" "<<jj<<" "<<kk<<endl;
            int id;cin>>id;
            if(id<0)return 0;
            if(id==0)break;
            int sw=uni(mt);
            if(sw==1)ii=id;
            else if(sw==2)jj=id;
            else kk=id;
        }
        cout<<"! "<<ii<<" "<<jj<<" "<<kk<<endl;
    }
}

#include<bits/stdc++.h>
using namespace std;
using ll=long long;

int main()
{
    int t;cin>>t;
    for(int i=0;i<t;i++)
    {
        int l1,r1,l2,r2;cin>>l1>>r1>>l2>>r2;
        vector<pair<ll,ll>>it1,it2;
        auto rec=[&](auto rec,int L,int R,int l,int r,vector<pair<ll,ll>>&v)->void
        {
            if(r<=L||l>=R)return;
            if(l<=L&&R<=r)
            {
                v.emplace_back(L,R);
                return;
            }
            rec(rec,L,(L+R)/2,l,r,v);
            rec(rec,(L+R)/2,R,l,r,v);
        };
        rec(rec,0,1<<25,l1,r1,it1);
        rec(rec,0,1<<25,l2,r2,it2);
        ll ans=0;
        for(auto[al,ar]:it1)
        {
            for(auto[bl,br]:it2)
            {
                ll a=ar-al,b=br-bl;
                if(a<b)swap(a,b);
                ans+=a/b;
            }
        }
        cout<<ans<<"\n";
    }
}

#include<bits/stdc++.h>
using namespace std;
using ll=long long;

ll dp[505][505];

int main()
{
    cin.tie(0)->sync_with_stdio(0);
    int t;cin>>t;
    for(int tc=0;tc<t;tc++)
    {
        ll n;cin>>n;
        vector<ll>vec(n);
        for(ll&i:vec)cin>>i;
        for(int i=0;i<n;i++)
        {
            for(int j=0;j<n;j++)dp[i][j]=-1e18;
        }
        auto value=[&](ll i,ll j,ll k)
        {
            return i*j*k;
        };
        for(int len=1;len<=n;len++)
        {
            for(int L=0;L<n;L++)
            {
                ll ans=0;
                ll R=(L+len-1)%n;
                if(len<=2)
                {
                    dp[L][R]=0;
                    continue;
                }
                if(len==3)
                {
                    dp[L][R]=max(0LL,value(vec[L],vec[(L+1)%n],vec[R]));
                    continue;
                }
                for(int i=(L+1)%n;i!=R;i=(i+1)%n)
                {
                    ll val=value(vec[L],vec[i],vec[R]);
                    if(i!=(L+1)%n)val+=dp[(L+1)%n][(i+n-1)%n];
                    if(i!=(R+n-1)%n)val+=dp[(i+1)%n][(R+n-1)%n];
                    ans=max(ans,val);
                }
                for(int i=L;i!=R;i=(i+1)%n)
                {
                    ans=max(ans,dp[L][i]+dp[(i+1)%n][R]);
                }
                dp[L][R]=ans;
            }
        }
        ll ans=0;
        for(int i=0;i<n;i++)
        {
            ans=max(ans,dp[i][(i+n-1)%n]);
        }
        cout<<ans<<"\n";
    }
}
